if ( address->host == INADDR_NONE ) {
    struct addrinfo hints, *res = NULL, *curr;
    int found = 0;

    SDL_memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if ( getaddrinfo(host, NULL, &hints, &res) == 0 && res != NULL ) {
        for ( curr = res; curr != NULL; curr = curr->ai_next ) {
            if ( curr->ai_family == AF_INET &&
                 curr->ai_addrlen >= sizeof(struct sockaddr_in) ) {
                struct sockaddr_in *sin =
                    (struct sockaddr_in *)curr->ai_addr;
                address->host = sin->sin_addr.s_addr;
                found = 1;
                break;
            }
        }
        if ( !found ) {
            for ( curr = res; curr != NULL; curr = curr->ai_next ) {
                if ( curr->ai_family == AF_INET6 &&
                     curr->ai_addrlen >= sizeof(struct sockaddr_in6) ) {
                    struct sockaddr_in6 *sin6 =
                        (struct sockaddr_in6 *)curr->ai_addr;
                    SDL_memcpy(&address->host,
                               &sin6->sin6_addr.s6_addr[12], 4);
                    found = 1;
                    break;
                }
            }
        }
        freeaddrinfo(res);
    }
    if ( !found ) {
        struct hostent *hp = gethostbyname(host);
        if ( hp ) {
            SDL_memcpy(&address->host, hp->h_addr_list[0], hp->h_length);
        } else {
            retval = -1;
        }
    }
}
